    /\ (getr R 1%bv = Z_to_bv 64 690460 /\ getr R 2%bv = Z_to_bv 64 S /\ getr R 10%bv = Z_to_bv 64 85943 /\ getr R 11%bv = Z_to_bv 64 (S + 24))
