  #[using="scfg IL HI Hsp DL can HCAP HLEN Lay DLL DLC LIOKX LEN CFG PL"] Lemma facts_offstkA : forall (M M2 : word -> option byte) (H2 : word -> bool) (A1 PTR OWN : Z) LB g,
